import { useEffect, useMemo, useState } from "react";
import { entityStore } from "../../lib/capabilities/composed/crud.js";
import { Link } from "../../lib/app";
import { useSemanticAction, useSemanticField, useSemanticSelection, useStatusRegion } from "../../lib/capabilities/composed/interaction-primitives.js";
import { runCreateMonthlyExpensesCustomBehavior } from "../../extensions/custom/create-monthly-expenses.js";
import { runEditAndDeleteExpenseCustomBehavior } from "../../extensions/custom/edit-and-delete-expense.js";
import { runRejectInvalidExpenseCustomBehavior } from "../../extensions/custom/reject-invalid-expense.js";
import { runViewMonthlySummaryCustomBehavior } from "../../extensions/custom/view-monthly-summary.js";

const store = entityStore("expense");
const categories = ["Food", "Travel", "Home", "Other"];
const format = (cents) => `$${(Number(cents) / 100).toFixed(2)}`;
const blank = { expenseDate: "2025-05-10", category: "Food", amount: "", note: "" };

export default function CreateMonthlyExpensesFlow() {
  const [records, setRecords] = useState([]);
  const [draft, setDraft] = useState(blank);
  const [selectedMonth, setSelectedMonth] = useState("2025-05");
  const [state, setState] = useState("loading");
  const [message, setMessage] = useState("");
  const [editing, setEditing] = useState(null);
  const [editAmount, setEditAmount] = useState("");
  const status = useStatusRegion({ label: "Ledger status" });
  const dateField = useSemanticField({ name: "expenseDate", label: "Expense date", value: draft.expenseDate, type: "text", onChange: (value) => setDraft((d) => ({ ...d, expenseDate: value })) });
  const amountField = useSemanticField({ name: "amount", label: "Amount", value: draft.amount, type: "text", onChange: (value) => setDraft((d) => ({ ...d, amount: value })) });
  const noteField = useSemanticField({ name: "note", label: "Note", value: draft.note, type: "text", onChange: (value) => setDraft((d) => ({ ...d, note: value })) });
  const categoryChoice = useSemanticSelection({ name: "category", value: draft.category, onSelect: (value) => setDraft((d) => ({ ...d, category: value })) });
  const saveAction = useSemanticAction({ name: "create-expense", label: "Save expense", onActivate: () => {} });
  const summaryAction = useSemanticAction({ name: "calculate-month-summary", label: "Calculate month total", onActivate: () => {} });

  const refresh = async () => { setState("loading"); try { const result = await store.list(); setRecords(result || []); setState((result || []).length ? "success" : "empty"); } catch { setState("error"); setMessage("We could not load your expenses. Please try again."); } };
  useEffect(() => { refresh(); }, []);
  const totals = useMemo(() => runCreateMonthlyExpensesCustomBehavior({ selectedMonth, records, expenseDate: "", amountCents: 0, category: "" }, { operation: "calculate-month-summary" }), [records, selectedMonth]);

  async function save(event) {
    event.preventDefault();
    const validation = runRejectInvalidExpenseCustomBehavior({ expenseDate: draft.expenseDate, category: draft.category, amount: draft.amount }, { operation: "create-expense" });
    if (!validation.valid) { setState("validation"); setMessage(validation.error); return; }
    setState("saving"); setMessage("Saving expense…");
    try {
      await store.create({ expenseDate: draft.expenseDate, category: draft.category, amount: draft.amount, amountCents: validation.amountCents, note: draft.note });
      await refresh(); setState("success"); setMessage("Saved — your expense is now in the ledger."); setDraft({ ...blank, expenseDate: draft.expenseDate });
    } catch { setState("error"); setMessage("Your expense could not be saved. Please try again."); }
  }
  async function saveEdit(event) {
    event.preventDefault();
    const validation = runEditAndDeleteExpenseCustomBehavior({ amount: editAmount }, { operation: "update-expense" });
    if (!validation.valid) { setMessage(validation.error); return; }
    try { await store.update(editing.id, { ...editing, amount: editAmount, amountCents: validation.amountCents }); await refresh(); setEditing(null); setMessage("Expense updated."); } catch { setMessage("The update could not be saved."); }
  }
  async function remove(item) { setMessage("Deleting expense…"); try { await store.remove(item.id); await refresh(); setMessage("Expense deleted."); } catch { setMessage("The expense could not be deleted."); } }

  const monthRecords = records.filter((item) => item.expenseDate?.slice(0, 7) === selectedMonth);
  return <div className="ledger-flow">
    <header className="ledger-header"><div><p className="eyebrow">Private monthly tracker</p><h1>Pocket Ledger</h1><p>Capture the small things. See the whole month.</p></div><Link to="/summary" className="summary-link">View Summary →</Link></header>
    <div className="ledger-grid"><section className="paper form-paper"><h2>New expense</h2><form aria-label="new expense form" onSubmit={save}>
      <label {...dateField.labelProps}>Expense date<input {...dateField.inputProps} data-thrallo-control="ctl_83000b03" type="date" /></label>
      <fieldset><legend>Category</legend><div className="category-options" {...categoryChoice.groupProps}>{categories.map((item) => <button key={item} type="button" value={item} data-thrallo-control="ctl_cf2f4271" {...categoryChoice.optionProps(item)}>{item}</button>)}</div></fieldset>
      <label {...amountField.labelProps}>Amount<input {...amountField.inputProps} data-thrallo-control="ctl_f785ce49" inputMode="decimal" placeholder="0.00" /></label>
      <label {...noteField.labelProps}>Note <span>(optional)</span><input {...noteField.inputProps} data-thrallo-control="ctl_919a0c3d" placeholder="What was this for?" /></label>
      <button {...saveAction.buttonProps} data-thrallo-action="act_9acbfaa4" type="submit" className="apricot">Save expense</button>
    </form><p {...status.statusProps} className={`status ${state}`}>{message}</p></section>
    <section className="paper total-paper"><p className="eyebrow">Selected month</p><label>Month selector<select aria-label="Selected Month" value={selectedMonth} data-thrallo-control="ctl_0cecb38a" onChange={(e) => setSelectedMonth(e.target.value)}><option value="2025-05">May 2025</option></select></label><strong>{totals.monthTotal}</strong><span>{monthRecords.length} expense{monthRecords.length === 1 ? "" : "s"} in this month</span><button {...summaryAction.buttonProps} data-thrallo-action="act_016e2721" onClick={() => setMessage(`Month total calculated: ${totals.monthTotal}`)}>Calculate total</button></section></div>
    <section className="paper list-paper"><div className="section-title"><div><p className="eyebrow">Month ledger</p><h2>Expenses</h2></div><b>{totals.monthTotal}</b></div>
      {state === "loading" ? <p>Loading expenses…</p> : state === "error" ? <p>Unable to load expenses.</p> : monthRecords.length === 0 ? <div className="empty"><span>◎</span><h3>No expenses yet</h3><p>Add your first expense to begin your monthly ledger.</p></div> : <ul>{monthRecords.map((item) => <li key={item.id}><div className="date-chip">{item.expenseDate}</div><div className="record"><b>{item.note || item.category}</b><small>{item.category} · {item.note || "No note"}</small></div><strong>{format(item.amountCents)}</strong><button type="button" data-thrallo-action="act_90cbb13b" onClick={() => { setEditing(item); setEditAmount(item.amount); }}>Edit</button><button type="button" data-thrallo-action="act_b6cbb3c7" onClick={() => remove(item)}>Delete</button></li>)}</ul>}
    </section>
    {editing && <section className="edit-panel paper"><h2>Edit {editing.note || "expense"}</h2><form aria-label="Lunch expense edit form" onSubmit={saveEdit}><p>{editing.expenseDate} · {editing.category} · {editing.note}</p><label>Replacement amount<input aria-label="Replacement amount" value={editAmount} onChange={(e) => setEditAmount(e.target.value)} /></label><button type="submit" data-thrallo-action="act_40f2ac59" className="apricot">Save changes</button><button type="button" onClick={() => setEditing(null)}>Cancel</button></form></section>}
  </div>;
}

export { runViewMonthlySummaryCustomBehavior };

