const money = (cents) => `$${(cents / 100).toFixed(2)}`;

export function runCreateMonthlyExpensesCustomBehavior(inputs, { operation }) {
  if (operation === "create-expense") {
    const valid = /^\d+(?:\.\d{1,2})?$/.test(inputs.amount || "") && Number(inputs.amount) > 0;
    if (!valid) return { valid: false, error: "Enter a positive amount with no more than two decimal places." };
    const [whole, fraction = ""] = inputs.amount.split(".");
    return { valid: true, amountCents: Number(whole) * 100 + Number(fraction.padEnd(2, "0")) };
  }
  const totals = { Food: 0, Travel: 0, Home: 0, Other: 0 };
  (inputs.records || []).filter((item) => item.expenseDate?.slice(0, 7) === inputs.selectedMonth).forEach((item) => {
    totals[item.category] = (totals[item.category] || 0) + Number(item.amountCents);
  });
  const total = Object.values(totals).reduce((sum, value) => sum + value, 0);
  return { monthTotal: money(total), foodTotal: money(totals.Food), travelTotal: money(totals.Travel), homeTotal: money(totals.Home), otherTotal: money(totals.Other) };
}

export function runEditAndDeleteExpenseCustomBehavior(inputs, { operation }) {
  if (operation !== "update-expense") return {};
  const valid = /^\d+(?:\.\d{1,2})?$/.test(inputs.amount || "") && Number(inputs.amount) > 0;
  if (!valid) return { valid: false, error: "Enter a positive amount with no more than two decimal places." };
  const [whole, fraction = ""] = inputs.amount.split(".");
  return { valid: true, amountCents: Number(whole) * 100 + Number(fraction.padEnd(2, "0")) };
}

export function runViewMonthlySummaryCustomBehavior(inputs, { operation }) {
  if (operation !== "calculate-month-summary") return {};
  const buckets = { Food: 0, Travel: 0, Home: 0, Other: 0 };
  (inputs.records || []).filter((item) => item.expenseDate?.slice(0, 7) === inputs.selectedMonth).forEach((item) => { buckets[item.category] = (buckets[item.category] || 0) + Number(item.amountCents); });
  const format = (value) => `$${(value / 100).toFixed(2)}`;
  return { monthTotal: format(Object.values(buckets).reduce((a, b) => a + b, 0)), foodTotal: format(buckets.Food), travelTotal: format(buckets.Travel), homeTotal: format(buckets.Home), otherTotal: format(buckets.Other) };
}

export function runRejectInvalidExpenseCustomBehavior(inputs, { operation }) {
  if (operation !== "create-expense") return {};
  const valid = /^\d+(?:\.\d{1,2})?$/.test(inputs.amount || "") && Number(inputs.amount) > 0;
  if (!valid) return { valid: false, error: "Enter a positive amount with no more than two decimal places." };
  const [whole, fraction = ""] = inputs.amount.split(".");
  return { valid: true, amountCents: Number(whole) * 100 + Number(fraction.padEnd(2, "0")) };
}

