import CreateMonthlyExpensesFlow from "../../components/create-monthly-expenses/CreateMonthlyExpensesFlow.jsx";

export default function PocketLedgerScreen() {
  return <main className="app-canvas"><CreateMonthlyExpensesFlow /></main>;
}

import { useEffect, useMemo, useState } from "react";
import { entityStore } from "../../lib/capabilities/composed/crud.js";
import { Link } from "../../lib/app";
import { useSemanticAction, useStatusRegion } from "../../lib/capabilities/composed/interaction-primitives.js";
import { runViewMonthlySummaryCustomBehavior } from "../../extensions/custom/view-monthly-summary.js";

const store = entityStore("expense");
export default function SummaryScreen() {
  const [records, setRecords] = useState([]); const [selectedMonth, setSelectedMonth] = useState("2025-05"); const [state, setState] = useState("loading");
  const status = useStatusRegion({ label: "Summary status" });
  const action = useSemanticAction({ name: "calculate-month-summary", label: "Calculate summary", onActivate: () => {} });
  useEffect(() => { store.list().then((items) => { setRecords(items || []); setState((items || []).length ? "success" : "empty"); }).catch(() => setState("error")); }, []);
  const totals = useMemo(() => runViewMonthlySummaryCustomBehavior({ selectedMonth, records, expenseDate: "", amountCents: 0, category: "" }, { operation: "calculate-month-summary" }), [records, selectedMonth]);
  return <main className="app-canvas"><div className="summary-page paper"><header className="ledger-header"><div><p className="eyebrow">Monthly overview</p><h1>Summary</h1><p>Every category, clearly counted.</p></div><Link className="summary-link" to="/">← Pocket Ledger</Link></header><label className="month-select">Month selector<select aria-label="Selected Month" data-thrallo-control="ctl_0cecb38a" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}><option value="2025-05">May 2025</option></select></label><div className="summary-total"><span>Monthly total</span><strong>{totals.monthTotal}</strong></div><button {...action.buttonProps} data-thrallo-action="act_016e2721" type="button">Calculate summary</button><p {...status.statusProps}>{state === "loading" ? "Loading summary…" : state === "empty" ? "No expenses yet for this month." : state === "error" ? "Unable to load summary." : "Summary ready."}</p><section><h2>Category totals</h2><div className="category-totals"><div><span>Food</span><b>{totals.foodTotal}</b></div><div><span>Travel</span><b>{totals.travelTotal}</b></div><div><span>Home</span><b>{totals.homeTotal}</b></div><div><span>Other</span><b>{totals.otherTotal}</b></div></div></section></div></main>;
}
